"""Independently check stored spatial maps then record the infrastructure probe."""
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import hashlib,json
import numpy as np
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'runs/flyvis_full_spatial_capture_probe_20261105';SRC=ROOT/'runs/flyvis_y1_latency_fp64_20261104'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=json.loads((OUT/'protocol.json').read_text(encoding='utf-8'));r=json.loads((OUT/'report.json').read_text(encoding='utf-8'));q=SRC/'outputs'/(p['case']['id']+'.npz');assert r['passed'] and sha(q)==p['reference_output_sha256'] and r['spatial_maps_sha256']==sha(OUT/'spatial_maps.npz') and r['protocol_sha256']==sha(OUT/'protocol.json');x=np.load(OUT/'spatial_maps.npz');ref=np.load(q);mask=np.load(SRC/'geometry.npz')['mask'];maps=x['maps'];assert maps.shape==(2,79,8,721);delta=float(np.max(np.abs(x['flow']-ref['flow'])));stage=float(np.max(np.abs(maps[:,:,:,mask].mean(-1)-ref['activity'][:,:,1:])));assert np.isfinite(maps).all() and delta<=1e-5 and stage<=1e-5 and r['parameters_unchanged'] and not r['cuda_initialized'];doc=dict(passed=True,report_sha256=sha(OUT/'report.json'),saved_maps_sha256=sha(OUT/'spatial_maps.npz'),flow_max_abs_diff=delta,activity_max_abs_diff=stage,scope='Independent comparison of saved arrays against original saved output, not an independent network rerun.');(OUT/'independent_audit.json').write_text(json.dumps(doc,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 msg=(f"Для одной ранее сохранённой синтетической последовательности штатная FlyVis на CPU повторно вычислена в FP64 с сохранением полных карт восьми типов T4/T5: форма {maps.shape}; максимальное отличие выхода декодера от сохранённого результата {delta:.3g}, средних активностей {stage:.3g}, оба меньше допуска 1e-5. Вычисление и сохранение заняли {r['elapsed_seconds']:.2f} с без учёта загрузки модели; файл {r['bytes']} байт. Параметры неизменны, CUDA не инициализирована. Это техническая проверка, не научный итог и не HOTA.")
 refs=['runs/flyvis_full_spatial_capture_probe_20261105/'+x for x in ('protocol.json','report.json','independent_audit.json')];(OUT/'РЕЗУЛЬТАТ.md').write_text('# Проверка сохранения карт T4/T5\n\n'+msg+'\n\nПроверены одна модель и одна последовательность; нет сравнения пространственного и усреднённого считывателей. Источники: '+', '.join('`'+x+'`' for x in refs)+'.\n',encoding='utf-8')
 cat=ROOT/'experiments/project_history.json';d=json.loads(cat.read_text(encoding='utf-8'));c=next(x for x in d['experiments'] if x['id']=='flyvis_full_spatial_capture_probe_v1');assert c['state']=='planned';c.update(state='infrastructure',done=datetime.now(ZoneInfo('Europe/Moscow')).date().isoformat(),obtained=msg+' Источники: '+', '.join(refs),interpretation='Сохранение пространственных карт технически возможно для проверенного случая с неизменным выходом.',decision='Использовать как техническое основание, отдельно согласовать научную проверку.',cannot_claim='Нет оценки полезности, причин запаздывания, независимых видео или HOTA.');c['acceptance'][0].update(met=True,evidence=refs[1]+'; '+refs[2]);c['evidence'] += [dict(kind='json',ref=x,claim='Результат или независимая сверка') for x in refs[1:]];cat.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 plan=ROOT/'dissertation/ЕДИНЫЙ_ПЛАН.md';raw=plan.read_bytes();marker='## Журнал изменений'.encode();nl=b'\r\n' if marker+b'\r\n' in raw else b'\n';now=datetime.now(ZoneInfo('Europe/Moscow'));entry=f'\n**{now:%d.%m.%Y, %H:%M} MSK** — Техническое сохранение пространственных карт T4/T5\n\n{msg} Источники: '+', '.join('`'+x+'`' for x in refs)+'.\n\n';assert raw.count(marker+nl)==1;plan.write_bytes(raw.replace(marker+nl,marker+nl+entry.encode(),1));print(msg)
if __name__=='__main__':main()
